begin;
-- Test-only privileged probe; public clients use only the Edge Function.
create function pg_temp.qa_tracking(token text) returns jsonb language sql security definer set search_path='' as $$select public.production_tracking(token)$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','ea8946ea-e093-4ad1-a886-954fb91187db',true);
do $$
declare unit uuid:='772039c9-622b-430c-90d7-8278adaa42aa';fleet uuid:='8925f6b3-7806-4080-9602-2c2e52da50cf';guy uuid:='ea8946ea-e093-4ad1-a886-954fb91187db';driver uuid:='84c799b3-f64f-402a-9c7e-86907f54e2b8';dj uuid:='b6a1f147-ae25-4b3e-bdb5-f35c5b4addba';cust uuid;site uuid;prod uuid;ord uuid;loadid uuid;load2 uuid;truck uuid;token text;key uuid;payload jsonb;response jsonb;failed boolean;stocks jsonb;
begin
 cust:=(public.production_command('customer',jsonb_build_object('business_unit_id',unit,'name','TRANSIENT QA customer'))->>'id')::uuid;
 site:=(public.production_command('site',jsonb_build_object('business_unit_id',unit,'customer_id',cust,'name','QA site','address','Not a real delivery'))->>'id')::uuid;
 prod:=(public.production_command('product',jsonb_build_object('business_unit_id',unit,'name','QA concrete','unit','m³','kind','product'))->>'id')::uuid;
 ord:=(public.production_command('order',jsonb_build_object('business_unit_id',unit,'customer_id',cust,'site_id',site,'product_id',prod,'quantity',16,'due_at',now()+interval '1 day','instructions','Internal dispatch instructions'))->>'id')::uuid;
 perform public.production_command('driver',jsonb_build_object('business_unit_id',fleet,'user_id',driver));
 select id into truck from public.assets where business_unit_id=fleet and status='active' limit 1;
 loadid:=(public.production_command('schedule',jsonb_build_object('order_id',ord,'fleet_unit_id',fleet,'driver_id',driver,'truck_id',truck,'quantity',8))->>'id')::uuid;
 failed:=false;begin perform public.production_command('schedule',jsonb_build_object('order_id',ord,'fleet_unit_id',fleet,'driver_id',driver,'truck_id',truck,'quantity',9));exception when raise_exception then failed:=true;end;if not failed then raise exception 'Over-dispatch permitted';end if;
 perform public.production_command('reference',jsonb_build_object('order_id',ord,'external_number','QA-AM-10458'));
 token:=public.production_command('tracking',jsonb_build_object('order_id',ord))->>'token';
 response:=pg_temp.qa_tracking(token);if response->>'reference'<>'QA-AM-10458' or response::text like '%Internal dispatch instructions%' then raise exception 'Public reference or private instructions exposed';end if;
 if pg_temp.qa_tracking(repeat('0',48)) is not null then raise exception 'Invalid token accepted';end if;
 perform set_config('request.jwt.claim.sub',driver::text,true);
 if not exists(select 1 from public.notifications where production_order_id=ord and user_id=driver) then raise exception 'Missing driver notification';end if;
 if not exists(select 1 from public.production_loads where id=loadid) then raise exception 'Driver cannot read assigned delivery';end if;
 response:=public.production_workspace();if jsonb_array_length(response->'customers')<>0 or jsonb_array_length(response->'orders')<>1 then raise exception 'Driver sees customer directory or other orders';end if;
 failed:=false;begin perform public.production_command('event',jsonb_build_object('load_id',loadid,'event','departed'));exception when raise_exception then failed:=true;end;if not failed then raise exception 'Departed before production ready';end if;
 perform set_config('request.jwt.claim.sub',guy::text,true);perform public.production_command('produce',jsonb_build_object('load_id',loadid));
 perform set_config('request.jwt.claim.sub',driver::text,true);
 failed:=false;begin perform public.production_command('event',jsonb_build_object('load_id',loadid,'event','departed','actor_id',guy));exception when raise_exception then failed:=true;end;if not failed then raise exception 'Queued account binding ignored';end if;
 key:=gen_random_uuid();payload:=jsonb_build_object('load_id',loadid,'event','departed','client_id',key,'captured_at',now());
 perform public.production_command('event',payload);perform public.production_command('event',payload);
 if(select count(*) from public.production_activity where client_id=key)<>1 then raise exception 'Retry duplicated driver event';end if;
 failed:=false;begin perform public.production_command('event',payload||'{"event":"completed"}');exception when raise_exception then failed:=true;end;if not failed then raise exception 'Retry key accepted changed payload';end if;
 failed:=false;begin perform public.production_command('event',jsonb_build_object('load_id',loadid,'event','completed'));exception when raise_exception then failed:=true;end;if not failed then raise exception 'Skipped arrival event';end if;
 perform public.production_command('message',jsonb_build_object('load_id',loadid,'body','PRIVATE QA driver message','customer_visible',true));
 response:=pg_temp.qa_tracking(token);if response::text like '%PRIVATE QA%' then raise exception 'Driver published internal notes';end if;
 perform set_config('request.jwt.claim.sub',dj::text,true);
 if exists(select 1 from public.production_orders where id=ord) or exists(select 1 from public.production_loads where id=loadid) then raise exception 'Unrelated operator reads deliveries';end if;
 failed:=false;begin perform public.production_command('message',jsonb_build_object('load_id',loadid,'body','Unauthorized'));exception when raise_exception then failed:=true;end;if not failed then raise exception 'Unrelated operator posted';end if;
 failed:=false;begin perform public.production_command('tracking',jsonb_build_object('order_id',ord));exception when raise_exception then failed:=true;end;if not failed then raise exception 'Unrelated operator created tracking link';end if;
 perform set_config('request.jwt.claim.sub',driver::text,true);
 perform public.production_command('event',jsonb_build_object('load_id',loadid,'event','arrived','captured_at',now()));
 perform public.production_command('event',jsonb_build_object('load_id',loadid,'event','completed','captured_at',now()));
 perform set_config('request.jwt.claim.sub',guy::text,true);
 if(select status from public.production_orders where id=ord)<>'confirmed' then raise exception 'Partial delivery closed whole order';end if;
 if not exists(select 1 from public.production_activity where order_id=ord and kind='reference_changed') then raise exception 'No reference audit';end if;
 load2:=(public.production_command('schedule',jsonb_build_object('order_id',ord,'fleet_unit_id',fleet,'driver_id',driver,'truck_id',truck,'quantity',8))->>'id')::uuid;
 perform public.production_command('produce',jsonb_build_object('load_id',load2));
 perform set_config('request.jwt.claim.sub',driver::text,true);
 perform public.production_command('event',jsonb_build_object('load_id',load2,'event','departed','captured_at',now()));perform public.production_command('event',jsonb_build_object('load_id',load2,'event','arrived','captured_at',now()));perform public.production_command('event',jsonb_build_object('load_id',load2,'event','completed','captured_at',now()));
 if(select status from public.production_orders where id=ord)<>'completed' then raise exception 'Fully delivered order not completed';end if;
 perform set_config('request.jwt.claim.sub',guy::text,true);
 response:=public.production_command('tracking',jsonb_build_object('order_id',ord));if pg_temp.qa_tracking(token) is not null then raise exception 'Replaced link still works';end if;perform set_config('ruel.qa.tracking',response->>'token',true);
end $$;
set local role service_role;
do $$begin if public.production_tracking(current_setting('ruel.qa.tracking')) is null then raise exception 'Edge service role cannot read tracking';end if;end$$;
set local role anon;
do $$begin if has_table_privilege('anon','public.production_orders','select') then raise exception 'Anonymous order-table access';end if;if has_function_privilege('anon','public.production_tracking(text)','execute') then raise exception 'Anonymous tracking RPC allowed';end if;end$$;
reset role;
select 'production_dispatch_passed' as result;
rollback;
